export function servicePreview(
  name = 'closure',
  id = serviceID,
): DeletionPreview {
  const p: DeletionPreview = JSON.parse(JSON.stringify(plans[name]))
  const resources = [p.targets[0]]
  for (const { node } of p.impacts.edges) {
    resources.push(node.target, node.referencingResource)
    if (node.parent) resources.push(node.parent)
  }
  for (const r of resources) {
    if (r.type === 'SERVICE' && r.id === serviceID) r.id = id
  }
  return p
}
export const serviceScenarios = Object.keys(plans)
